/* Styling Native Checkbox into a Sliding Switch */
input[type="checkbox"][role="switch"] {
  appearance: none;
  width: 44px;
  height: 24px;
  background: #334155;
  border-radius: 999px;
  position: relative;
  cursor: pointer;
  transition: background-color 0.2s;
}
input[type="checkbox"][role="switch"]::before {
  content: "";
  position: absolute;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  top: 3px; left: 3px;
  background: #ffffff;
  transition: transform 0.2s;
}
input[type="checkbox"][role="switch"]:checked {
  background: #059669;
}
input[type="checkbox"][role="switch"]:checked::before {
  transform: translateX(20px);
}

