table {
  width: 100%;
  border-collapse: collapse;
}
th, td {
  padding: 10px 14px;
  border-bottom: 1px solid var(--border-subtle);
  text-align: left;
}
th {
  background: var(--surface-elevated);
}

/* Removing native spin buttons if custom UI is required */
input[type="number"]::-webkit-inner-spin-button,
input[type="number"]::-webkit-outer-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

main {
  max-width: 1200px;
  margin: 0 auto;
}
header, footer {
  padding: 24px;
}

nav[aria-label="Breadcrumb"] ol {
  display: flex;
  gap: 8px;
  list-style: none;
}
nav[aria-label="Breadcrumb"] li + li::before {
  content: "/";
  color: var(--text-muted);
  margin-right: 8px;
}

.nested-details-tree details {
  padding-left: 14px;
}

.snap-carousel {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
}
.snap-slide {
  flex: 0 0 100%;
  scroll-snap-align: center;
}

output {
  display: block;
  padding: 10px 14px;
  background: var(--surface-card);
  border-radius: 6px;
}

/* Modern Anchor Positioning for Tooltips */
.anchor-btn {
  anchor-name: --tip-btn;
}
.modern-tip {
  position: absolute;
  position-anchor: --tip-btn;
  top: anchor(bottom);
  left: anchor(center);
  transform: translateX(-50%);
}

.toolbar-group {
  display: inline-flex;
  gap: 4px;
  background: var(--surface-card);
  padding: 4px;
  border-radius: 6px;
}
